<?php $stayMoney=static fn(int $v):string=>number_format($v,0,',','.').' đ'; ?>
<?php if($isStayIndex):?>
<section><h1><?=$en?'Places to stay':'Lưu trú'?></h1><p><?=$en?'Explore rooms, then check prices for your dates.':'Chọn cơ sở và xem giá phòng theo ngày lưu trú.'?></p>
<?php if(!$stayCatalog['enabled']):?><p><?=$en?'Stay listings are currently unavailable.':'Danh mục lưu trú hiện chưa mở.'?></p>
<?php elseif(!$stayCatalog['items']):?><p><?=$en?'No properties are available yet.':'Chưa có cơ sở lưu trú đang mở.'?></p>
<?php else:?><div class="page-grid"><?php foreach($stayCatalog['items'] as $s):?><a class="page-card" href="<?=$e($s['localePaths'][$lang])?>"><?php if(isset($s['coverId'])&&$media(['id'=>$s['coverId']])):?><img class="product-thumb" src="<?=$e($media(['id'=>$s['coverId']]))?>" alt="<?=$e($s['name'])?>" loading="lazy"><?php endif;?><p class="eyebrow"><?=$e($s['destination'])?></p><h2><?=$e($s['name'])?></h2><p><?=$e($s['address'])?></p><p><?=$en?'Base rate from ':'Giá cơ bản từ '?><?=$e($stayMoney($s['fromPrice']))?><?=$en?'/night':'/đêm'?></p><span><?=$en?'View rooms and prices':'Xem phòng và giá'?> ↗</span></a><?php endforeach;?></div><?php endif;?></section>
<?php else:?>
<article><p class="eyebrow"><?=$e($stay['destination'])?></p><h1><?=$e($stay['name'])?></h1><p><?=$e($stay['address'])?></p><?php if($stay['mapUrl']):?><p><a href="<?=$e($stay['mapUrl'])?>" target="_blank" rel="noopener noreferrer"><?=$en?'View map':'Xem bản đồ'?></a></p><?php endif;?>
<?php if(isset($stay['coverId'])&&$media(['id'=>$stay['coverId']])):?><img class="product-thumb" src="<?=$e($media(['id'=>$stay['coverId']]))?>" alt="<?=$e($stay['name'])?>"><?php endif;?><p class="stay-text"><?=$e($stay['description'])?></p>
<?php if($stay['galleryIds']):?><div class="page-grid"><?php foreach($stay['galleryIds'] as $id)if($media(['id'=>$id])):?><img class="product-thumb" src="<?=$e($media(['id'=>$id]))?>" alt="<?=$e($stay['name'])?>" loading="lazy"><?php endif;?></div><?php endif;?>
<h2><?=$en?'Rooms':'Loại phòng'?></h2><div class="page-grid"><?php foreach($stay['rooms'] as $r):?><section class="page-card"><?php if(isset($r['imageId'])&&$media(['id'=>$r['imageId']])):?><img class="product-thumb" src="<?=$e($media(['id'=>$r['imageId']]))?>" alt="<?=$e($r['name'])?>" loading="lazy"><?php endif;?><h3><?=$e($r['name'])?></h3><p class="stay-text"><?=$e($r['description'])?></p><p><?=$e($r['beds'])?></p><p><?=$en?'Capacity: ':'Sức chứa: '?><?=$e($r['maxGuests'])?><?=$en?' guests · up to ':' khách · tối đa '?><?=$e($r['maxAdults'])?><?=$en?' adults · up to ':' người lớn · '?><?=$e($r['maxChildren'])?><?=$en?' children':' trẻ em'?></p><p><?=$en?'Base rate: ':'Giá cơ bản: '?><?=$e($stayMoney($r['price']))?><?=$en?'/night':'/đêm'?></p></section><?php endforeach;?></div>
<h2><?=$en?'Check room prices':'Xem giá phòng theo ngày'?></h2><form class="quote-form" id="stay-quote-form" data-hotel-id="<?=$e($stay['id'])?>" data-locale="<?=$lang?>"><fieldset><div class="contact-form-grid"><label><?=$en?'Room type':'Loại phòng'?><select name="roomId"><?php foreach($stay['rooms'] as $r):?><option value="<?=$e($r['id'])?>"><?=$e($r['name'])?></option><?php endforeach;?></select></label><label><?=$en?'Check-in':'Ngày nhận phòng'?><input name="checkIn" type="date" required></label><label><?=$en?'Check-out':'Ngày trả phòng'?><input name="checkOut" type="date" required></label><?php foreach([['rooms',$en?'Rooms':'Số phòng',1,20],['adults',$en?'Adults':'Số người lớn',1,100],['children',$en?'Children':'Số trẻ em',0,100]] as [$key,$label,$min,$max]):?><label><?=$label?><input name="<?=$key?>" type="number" min="<?=$min?>" max="<?=$max?>" step="1" value="<?=$min?>" required></label><?php endforeach;?><label><?=$en?'Stay voucher (optional)':'Voucher phòng (nếu có)'?><input name="voucherCode" maxlength="40" autocomplete="off"></label></div><button class="button" type="submit"><?=$en?'Check prices':'Xem giá phòng'?></button></fieldset><p id="stay-quote-status" role="status"></p></form><section id="stay-quote-result"></section><p class="muted"><?=$en?'Prices do not reserve rooms. Contact us to confirm your stay.':'Xem giá chưa giữ phòng. Liên hệ để xác nhận nhu cầu lưu trú.'?> <a href="<?=$en?'/en/contact':'/lien-he'?>"><?=$en?'Contact us':'Liên hệ'?></a></p>
<h2><?=$en?'Amenities':'Tiện ích'?></h2><p class="stay-text"><?=$e($stay['amenities'])?></p><h2><?=$en?'Policies':'Chính sách'?></h2><p class="stay-text"><?=$e($stay['policy'])?></p><p><?=$en?'Check-in / check-out: ':'Nhận phòng / trả phòng: '?><?=$e($stay['checkInTime'])?> / <?=$e($stay['checkOutTime'])?> · <?=$e($stay['minNights'])?>–<?=$e($stay['maxNights'])?> <?=$en?'nights':'đêm'?></p></article>
<?php endif;?>
